export async function GET() {
  try {
    await connectDB()
    const results = { admin:{ status:'', email:'' }, notes:{ added:0, skipped:0 }, questions:{ added:0, skipped:0 } }

    // ── Create Admin if not exists ──────────────────────────
    const existing = await User.findOne({ role:'admin' })
    if (existing) {
      results.admin = { status:'already_exists', email:existing.email }
    } else {
      const hashed = await bcrypt.hash('Admin@Vidyalaya123', 12)
      const admin = await User.create({ name:'Shivam Tiwari', email:'shivam@vidyalaya.edu', password:hashed, role:'admin', class:'XII', rollNumber:'ADMIN001', isActive:true, createdAt:new Date() })
      results.admin = { status:'created', email:admin.email }
    }

    // ── Seed all Notes ──────────────────────────────────────
    for (const note of NOTES) {
      const exists = await Note.findOne({ title: note.title })
      if (exists) { results.notes.skipped++; continue }
      await Note.create(note)
      results.notes.added++
    }

    // ── Seed all Questions ──────────────────────────────────
    for (const q of QUESTIONS) {
      const exists = await Question.findOne({ question: q.question })
      if (exists) { results.questions.skipped++; continue }
      await Question.create({ ...q, isActive:true })
      results.questions.added++
    }

    return NextResponse.json({
      success: true,
      message: '✅ FULL SETUP COMPLETE! Your platform is 100% ready.',
      summary: {
        admin: results.admin,
        notes_added: results.notes.added,
        notes_skipped: results.notes.skipped,
        questions_added: results.questions.added,
        questions_skipped: results.questions.skipped,
      },
      login_now: {
        url: '/login',
        email: results.admin.status === 'created' ? 'shivam@vidyalaya.edu' : results.admin.email,
        password: results.admin.status === 'created' ? 'Admin@Vidyalaya123' : '(use your existing password)',
      },
      next_steps: [
        '1. Go to /login and sign in with above credentials',
        '2. CHANGE YOUR PASSWORD immediately after first login',
        '3. Go to Admin → Students to add your students',
        '4. All notes are live — students can read them now!',
        '5. Go to Admin → Tests to create your first test',
        '6. IMPORTANT: Delete this file app/api/setup-all/route.js from GitHub!',
      ],
    })
  } catch (error) {
    return NextResponse.json({
      success: false,
      error: error.message,
      fix: 'Check that MONGODB_URI environment variable is correctly set in Vercel dashboard',
      tip: 'Make sure your MongoDB Atlas IP whitelist includes 0.0.0.0/0 (Allow from anywhere)',
    }, { status: 500 })
  }
}
